import React from "react";

function MsgHeading({ title, para }) {
  return (
    <div className=" flex justify-around">
      <div className=" text-yellow-400 text-xl w-full md:w-1/2">{title}</div>
      <p className="w-full md:w-1/2">{para}</p>
    </div>
  );
}

export default MsgHeading;
